 function clean(value,depth=0){if(depth>14)throw Error('Workspace nesting is too deep.');if(value===null||typeof value==='boolean')return value;if(typeof value==='number'){if(!Number.isFinite(value))throw Error('Invalid number.');return value}if(typeof value==='string'){if(value.length>10000)throw Error('A workspace field is too long.');return value}if(Array.isArray(value)){if(value.length>2000)throw Error('Too many workspace items.');return value.map(v=>clean(v,depth+1))}if(value&&typeof value==='object'){const out={};if(Object.keys(value).length>2000)throw Error('Too many workspace fields.');for(const [key,item]of Object.entries(value)){if(forbidden.has(key))throw Error('Invalid workspace key.');out[key]=clean(item,depth+1)}return out}throw Error('Invalid workspace value.')}
